function fleetColumn(yard){if(!yard||!account.permissions.includes('operations.manage'))return '';const workers=state.resources.filter(r=>r.type==='WORKER'&&r.location===yard.id).length,forklifts=state.resources.filter(r=>r.type==='FORKLIFT'&&r.location===yard.id).length,heavy=state.trucks.filter(t=>t.yard===yard.id&&t.payload>=10000000).length,light=state.trucks.filter(t=>t.yard===yard.id&&t.payload<10000000).length,stillages=state.containers.filter(c=>c.location===yard.id&&c.type==='STILLAGE').length;return '<div class="quick-grid fleet-column">'+quickRow('FORKLIFT','forklift',forklifts,'Forklift')+quickRow('WORKER','worker',workers,'Worker')+quickRow('STILLAGE','stillage',stillages,'Empty stillage')+quickRow('TRUCK2','truck',light,'Truck 2 tonne')+quickRow('TRUCK12','truck',heavy,'Truck 12.5 tonne')+'</div>';}
