// ----- Materials list as the stock catalogue: a hero with catalogue counters over a stock-rack scene, the components as tiles grouped by category (component icons, system marks, weight and pack chips, verification pills, missing figures flagged), and intake as an action card (systems as a segmented control, search, Record as, a quantity stepper per row). The page's own new controls are handled by listeners on the document (mlBindOnce), so the shared bindPage is unchanged. -----
import {mlImg,mlSceneArt} from './art.js';
let mlSearch='',mlGaps=false,mlBound=false,mlOwner=null,mlAnchor=null,mlSig='';const mlFold=new Map(),mlQty=new Map(),mlText=new Map(),mlInHay=new Map(),mlH=new Map();
// Category groups start open, except on a phone where the closed groups read as an index; a group the viewer opens or closes (a click on its summary) stays that way through rebuilds.
