 const sub=sum.total?num(sum.total)+(sum.total===1?' component':' components')+' across '+systems.length+(systems.length===1?' system':' systems')+(sum.verified?' &middot; '+num(sum.verified)+' source verified':'')+(sum.demo?' &middot; '+num(sum.demo)+' demo only':''):'No components yet.'+(isOps()&&systems.length?' Use Import materials below to add your catalogue.':'');
 // Yard balances reach operations roles only; a supervisor gets the stock at their own sites instead of a false zero.
