function mlFilter(){const root=document.querySelector('.page-materials .ml-cat');if(!root)return;const q=mlSearch.trim().toLowerCase();let total=0;for(const g of root.querySelectorAll('[data-ml-group]')){let n=0,gaps=0;for(const row of g.querySelectorAll('[data-ml-row]')){const hide=!!q&&!(mlText.get(row.dataset.mlRow)??row.textContent.toLowerCase()).includes(q);if(row.hidden!==hide)row.hidden=hide;if(!hide){n++;if(row.classList.contains('ml-g'))gaps++;}}const key=g.dataset.mlGroup;g.hidden=!n;mlOpen(g,!!q||(mlFold.get(key)??!mlPhone()));const c=g.querySelector('[data-ml-count]');if(c)c.textContent=num(n);const gb=g.querySelector('[data-ml-gap]');if(gb)mlSetGap(gb,gaps);const j=root.querySelector('[data-ml-jump="'+key+'"]');if(j){j.hidden=!n;const b=j.querySelector('b');if(b)b.textContent=num(n);}total+=n;}const none=root.querySelector('[data-ml-none]'),rows=root.querySelectorAll('[data-ml-row]').length;if(none){none.hidden=!!total||!rows;const b=none.querySelector('[data-ml-q]');if(b)b.textContent=mlSearch.trim();}const pill=root.querySelector('[data-ml-pill]');if(pill)pill.textContent=num(q?total:rows)+' of '+num(state.products.filter(p=>!p.retired).length);}
// Intake search: the shared handler matches a row's whole text, which now also holds the pack and weight words; this re-applies the render's own filter (name, category, reference) and shows the "nothing matches" line.
function mlIntakeFilter(){const list=document.querySelector('.page-materials .ml-in-list');if(!list)return;const q=intakeSearch.trim().toLowerCase();let any=false;for(const row of list.querySelectorAll('[data-intake-row]')){const h=mlInHay.get(row.dataset.focusScope?.slice(7));const hide=!!q&&!(h??row.textContent.toLowerCase()).includes(q);if(row.hidden!==hide)row.hidden=hide;if(!hide)any=true;}const none=list.querySelector('[data-ml-in-none]');if(none)none.hidden=any;}
// Before a rebuild: the heights of the open groups and intake rows, so the rebuilt ones (content-visibility skips the off-screen ones) are estimated at their real size and a restored scroll position lands on the same rows.
