// No header row: the name is taken to be the first column and the system the column whose cells are mostly system names; the owner matches the rest.
export function miGuessByContent(rows,systems){const map={};for(const f of MI_FIELDS)map[f.k]=-1;const sample=(rows??[]).slice(0,50),width=Math.max(0,...sample.map(r=>r.length));map.name=width?0:-1;let best=0;for(let i=0;i<width;i++){const hits=sample.filter(r=>miSystemOf(r[i],systems)).length;if(hits>best&&hits*2>=sample.length){best=hits;map.system=i;}}if(map.system===0)map.name=width>1?1:-1;return {map,unit:null,notes:[]};}
// A reference for a row without one: NOREF-<SYSTEM>-<name>; a long name is cut and ends in a short hash of the whole name, so two long names that start alike still differ.
const miHash=s=>{let h=2166136261;for(const c of String(s))h=Math.imul(h^c.codePointAt(0),16777619)>>>0;return h.toString(36).toUpperCase().padStart(5,'0').slice(-5);};
