  if(e.g!=null&&e.pack!=null&&e.g*e.pack>4000000)e.warnings.push('A full stillage of '+num(e.pack)+' would weigh '+(e.g*e.pack/1e6).toFixed(1)+' t: is the weight for one piece?');
  const vr=get(r,'verification',line),v=miVerification(vr);e.verification=v??(MI_VER.includes(cfg.verDefault)?cfg.verDefault:'COMPANY CONFIGURED');if(vr&&!v)e.warnings.push('Verification "'+vr+'" not recognised: saved as '+miVerLabel(e.verification));
