export function miUpdate(e,p,file=''){return {product:p.id,unitWeight:e.g??p.unitWeight??null,packQuantity:e.pack??p.packQuantity??null,sourceNote:(e.document?e.document+(e.page?', page '+e.page:''):'Materials import'+(file?' ('+file+')':'')).slice(0,250),reason:'Updated by the materials import'};}
// Batches for importCatalogue: at most maxRows products and a JSON body (UTF-8 bytes) under maxBytes, so each request stays under the server's 16 KB limit.
