function miRunBody(){const p=mi.progress??{done:0,total:1,label:''},pct=p.total?Math.round(p.done*100/p.total):0;return '<div class="mi-run" role="status" aria-live="polite"><span class="mi-run-art">'+mlImg('spr-forklift-load')+'</span><div><b>'+esc(p.label||'Importing…')+'</b><i class="mi-bar" aria-hidden="true"><b data-style="width:'+pct+'%"></b></i><small>'+num(p.done)+' of '+num(p.total)+' rows · keep this page open</small></div></div>';}
function miDoneBody(){const r=mi.result??{added:[],updated:[],skipped:[],errors:[]},gaps=r.added.filter(a=>a.g==null||a.pack==null).length;const item=x=>'<li><span class="mi-line">'+x.line+'</span><span><strong>'+esc(x.name||'(no name)')+'</strong><small>'+esc(x.reason)+'</small></span></li>';
 return '<div class="mi-stats">'+['add','up','skip','bad'].map((k,i)=>'<div class="mi-stat '+k+'"><b>'+num([r.added,r.updated,r.skipped,r.errors][i].length)+'</b><span>'+['Added','Updated','Skipped','Not imported'][i]+'</span><small>'+['new components','weight / pack','left as they were',r.errors.length?'see the reasons below':'none'][i]+'</small></div>').join('')+'</div>'
 +(r.errors.length?'<h3 class="mi-sub">Not imported</h3><ul class="mi-result bad">'+r.errors.slice(0,300).map(item).join('')+'</ul>'+(r.errors.length>300?'<p class="mi-note">and '+num(r.errors.length-300)+' more</p>':''):'')
 +(r.skipped.length?'<h3 class="mi-sub">Skipped</h3><ul class="mi-result">'+r.skipped.slice(0,100).map(item).join('')+'</ul>'+(r.skipped.length>100?'<p class="mi-note">and '+num(r.skipped.length-100)+' more</p>':''):'')
 +(r.warned?.length?'<h3 class="mi-sub">Added, worth a check</h3><ul class="mi-result warn">'+r.warned.slice(0,100).map(item).join('')+'</ul>'+(r.warned.length>100?'<p class="mi-note">and '+num(r.warned.length-100)+' more</p>':''):'')
 +(gaps?'<p class="mi-callout-line">'+num(gaps)+(gaps===1?' new component has':' new components have')+' no weight or pack size yet.</p>':'')
 +'<div class="mi-actions"><button type="button" class="secondary" data-mi-act="again" id="mi-again">Import another file</button>'+(gaps?'<button type="button" class="mi-go" data-mi-act="fix-open">Enter the missing figures</button>':'')+'</div>';}
export function miImportPanel(){if(!isOps()||!miSystems().length)return '';const body=mi.step==='map'&&mi.rows?miMapBody():mi.step==='check'&&mi.rows?miCheckBody():mi.step==='run'?miRunBody():mi.step==='done'?miDoneBody():miInputBody();
 return '<section class="panel ml-card mi-card" id="mi-import" aria-labelledby="mi-import-h" data-focus-scope="mi-import">'+mlHead('spr-forklift-load','<span id="mi-import-h">Import materials</span>','Add many components at once from a spreadsheet: paste the rows or upload a CSV file. You check every row before anything is saved.',mi.step==='map'||mi.step==='check'?'<button type="button" class="secondary mi-reset" data-mi-act="again">Start again</button>':'')+miStepper()+'<div class="mi-body">'+body+'</div></section>';}
const MI_UP='<svg class="stk-dl" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 15V4M7.5 8.5 12 4l4.5 4.5M5 20h14"/></svg>';
// Where the owner adds a catalogue, said the same way everywhere: the Import materials card on the Materials list (where = 'above' / 'below' it on that page).
export const miWhere=where=>!isOps()?'An owner or general manager adds the catalogue with Import materials on the Materials list.':!miSystems().length?'Switch on a scaffold system on the Account page first, then add its components with Import materials.':'Add them with <a class="mi-link" href="#mi-import" data-mi-act="goto-import">Import materials</a> '+where+'.';
// ---- The fixer ----
const miFixList=()=>{const tab=componentTab,all=state.products.filter(p=>!p.retired&&(tab==='ALL'||p.system===tab)),q=miFix.search.trim().toLowerCase();const list=mlGroups(all.filter(p=>p.unitWeight==null||p.packQuantity==null||miFix.done.has(p.id))).flatMap(([,l])=>l).filter(p=>!q||mlHay(p).includes(q));return [...list.filter(p=>p.unitWeight==null),...list.filter(p=>p.unitWeight!=null)];};
const miHasDraft=d=>[d?.w,d?.k,d?.s].some(x=>String(x??'').trim());
// One component: the same three columns on every row (Weight, kg | Pieces per stillage | Source / note). A figure it has shows as text in its column, a missing one is an empty box
// (no example number that could pass for a real figure); the row's own Save shows once something is typed, and Save all filled rows is the main action.
function miFixRow(p){const done=miFix.done.get(p.id),d=miFix.draft.get(p.id)??{},m=miFix.msg.get(p.id),w=p.unitWeight==null,k=p.packQuantity==null;
 const box=(key,label,mode,extra='')=>'<label class="mi-fld mi-fld-'+key+'"><span class="mi-fld-l">'+label+'</span><input id="mi-'+key+'-'+p.id+'" data-mi-fix="'+key+'" data-mi-id="'+p.id+'" value="'+esc(d[key]??'')+'" inputmode="'+mode+'" autocomplete="off" maxlength="'+(key==='s'?200:24)+'"'+extra+'></label>';
 const text=(key,label,v,t)=>'<div class="mi-fld mi-fld-'+key+'"><span class="mi-fld-l">'+label+'</span><span class="mi-known'+(v==null?' nil':'')+'">'+t+'</span></div>';
 const wt=w&&!done?box('w','Weight, kg','decimal'):text('w','Weight, kg',p.unitWeight,w?'Not known yet':kg(p.unitWeight));
 const pk=k&&!done?box('k','Pieces per stillage','numeric'):text('k','Pieces per stillage',p.packQuantity,k?'Not known yet':num(p.packQuantity));
 const note=done?'<div class="mi-fld mi-fld-s"><span class="mi-fld-l">Source / note</span><span class="mi-known saved"><span class="ml-ver co">Company figures</span>'+esc(done.note)+'</span></div>':box('s','Source / note','text',miFix.note?' placeholder="'+esc('Uses: '+miFix.note)+'"':'');
 const act=done?'<span class="mi-fix-ok">Saved</span>':'<button type="button" class="secondary mi-save" data-mi-act="fix-save" data-mi-id="'+p.id+'" aria-label="Save the figures for '+esc(p.name)+'"'+(miFix.busy?' disabled':'')+'>Save</button>';
 return '<li class="mi-fix-row'+(done?' saved':'')+(!done&&miHasDraft(d)?' has-input':'')+'" data-mi-fix-row="'+p.id+'" data-focus-scope="mifix:'+p.id+'"><span class="ml-slot">'+componentIcon(p)+'</span><span class="ml-name"><strong>'+mlNameHTML(p.name)+'</strong><small>'+mlMark(p.system)+'<span class="ml-ref">'+esc(p.reference??'')+'</span><span class="ml-maker">'+esc(p.manufacturer??'')+'</span>'+'</small>'+alMinChip(p,true)+'</span>'+wt+pk+note+act+(m?'<p class="mi-fix-msg'+(m.bad?' bad':'')+'" role="status">'+esc(m.text)+'</p>':'')+'</li>';}
const miFilled=()=>[...miFix.draft].filter(([id,d])=>(String(d.w??'').trim()||String(d.k??'').trim())&&!miFix.done.has(id)).length;
function miFixListHTML(){const list=miFixList(),shown=list.slice(0,miFix.shown);
 return '<div id="mi-fix-body"><ul class="mi-fix-list">'+(shown.length?shown.map(miFixRow).join(''):'<li class="mi-fix-none">'+mlEmpty('ml-scale',miFix.search.trim()?'Nothing matches':'Every figure is in',miFix.search.trim()?'Try a shorter word.':'Each component here has a unit weight and a pack size.')+'</li>')+'</ul>'+(list.length>shown.length?'<div class="mi-more"><button type="button" class="secondary" data-mi-act="fix-more">Show '+num(Math.min(60,list.length-shown.length))+' more</button><small>'+num(shown.length)+' of '+num(list.length)+' shown</small></div>':'')+'</div>';}
export function miFixPanel(){if(!miFix.open||!isOps())return '';const tab=componentTab,sys=tab==='ALL'?null:miSystems().find(s=>s.id===tab),n=miFixList().filter(p=>!miFix.done.has(p.id)).length,filled=miFilled();
 return '<section class="panel ml-card mi-fix" id="mi-fix" aria-labelledby="mi-fix-h">'+mlHead('ml-scale','<span id="mi-fix-h" tabindex="-1">Fix missing figures</span>','Enter the real unit weight and pack size from the supplier&rsquo;s datasheet or your own weighing, and say where each figure comes from. Figures saved here are marked <b>Company figures</b>, not demo. Leave a box empty when you don&rsquo;t know it yet.','<span class="ml-pill">'+num(n)+(n===1?' component':' components')+(sys?' in '+esc(sys.name):'')+'</span><button type="button" class="secondary mi-close" data-mi-act="fix-close" aria-label="Close the missing figures list">Done</button>')
 +'<div class="mi-fix-tools" data-focus-scope="mi-fix-tools"><label class="ml-search">Find a component<span class="ml-search-box"><i class="ml-glass" aria-hidden="true"></i><input id="mi-fix-search" type="search" value="'+esc(miFix.search)+'" placeholder="Name, reference, category…"></span></label><label class="mi-fix-note">Source for rows with no note of their own<input id="mi-fix-note" maxlength="200" value="'+esc(miFix.note)+'"></label></div>'
 +miFixListHTML()+'<div class="mi-actions mi-sticky"><span class="mi-sum">Figures saved here are marked Company figures</span><button type="button" class="mi-go" data-mi-act="fix-all" id="mi-fix-all"'+(miFix.busy?' disabled':'')+'>Save all filled rows <b>'+num(filled)+'</b></button></div></section>';}
// The entry point: with "Missing figures only" on, the catalogue card offers the list to fill in (owners and managers only).
export const miGapsCallout=sum=>mlGaps&&isOps()&&sum.gaps?'<div class="mi-callout"><span class="mi-callout-art">'+mlImg('ml-scale')+'</span><p><b>'+num(sum.gaps)+(sum.gaps===1?' component is':' components are')+' missing a weight or pack size.</b> Enter the real figures from your supplier&rsquo;s documents or your own weighing.</p><button type="button" class="mi-go" data-mi-act="fix-open" id="mi-fix-open">'+(miFix.open?'Go to the list':'Enter the missing figures')+'</button></div>':'';
function miSwap(id,html){if(typeof document==='undefined')return;const el=document.getElementById(id);if(!el)return;const f=document.activeElement?.id,t=document.createElement('template');t.innerHTML=html;const n=t.content.firstElementChild;if(n)el.replaceWith(n);else el.remove();if(f&&(document.activeElement===document.body||!document.activeElement))document.getElementById(f)?.focus({preventScroll:true});}
const miRedraw=()=>miSwap('mi-import',miImportPanel()),miFixRedraw=()=>miSwap('mi-fix',miFixPanel());
const miTop=id=>{const el=document.getElementById(id);if(el&&el.getBoundingClientRect().top<0)el.scrollIntoView({block:'start'});};
const miMotion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth';
// On a phone (or any touch screen) the fixer opens on its heading: focusing a box would pop the keyboard up over the explanation and the shared note.
const miTouch=()=>{try{return matchMedia('(pointer:coarse)').matches||innerWidth<700;}catch{return false;}};
// Opens the fixer from anywhere on the page (the Missing figures only callout, the hero's Missing figures tile, the import result, the Home guide).
export function miOpenFix(){mlGaps=true;miFix.open=true;render();const el=document.getElementById('mi-fix');el?.scrollIntoView({block:'start'});if(miTouch())document.getElementById('mi-fix-h')?.focus({preventScroll:true});else document.querySelector('#mi-fix input[data-mi-fix]')?.focus({preventScroll:true});}
// Scrolls to the import card; on its first step the cursor goes into the paste box.
export function miGoImport(){const el=document.getElementById('mi-import');if(!el)return false;el.scrollIntoView({block:'start',behavior:miMotion()});document.getElementById('mi-text')?.focus({preventScroll:true});return true;}
function miStart(){mi.error='';if(!mi.text.trim()){mi.error='Paste some rows or choose a file first.';miRedraw();return;}if(/\u0000/.test(mi.text)||/^PK\u0003\u0004/.test(mi.text)){mi.error='This looks like an Excel workbook (.xlsx), not a CSV. In Excel choose File › Save As › CSV, or copy the rows and paste them here.';mi.text='';mi.file='';miRedraw();return;}
 if(mi.text.length>5000000){mi.error='That is more than 5 MB of text. Split it into smaller files.';miRedraw();return;}
 miRead();const n=(mi.rows??[]).slice(mi.header+1).filter(r=>r.some(c=>String(c).trim())).length;if(n<1){mi.error='No rows found'+(mi.header>=0?' under the header row':'')+'.';mi.step='input';miRedraw();return;}if(n>5000){mi.error='That is '+num(n)+' rows: import at most 5,000 at a time.';mi.step='input';miRedraw();return;}
 mi.step='map';mi.sysMap={};mi.decisions={};mi.edits={};mi.mapOpen=false;mi.filter='all';mi.shown=50;miRedraw();miTop('mi-import');}
function miFile(file){if(!file)return;mi.error='';if(file.size>5*1024*1024){mi.error='That file is larger than 5 MB. Split it into smaller files.';miRedraw();return;}const r=new FileReader();r.onload=()=>{try{mi.text=miDecode(new Uint8Array(r.result));}catch{mi.error='Could not read that file.';miRedraw();return;}mi.file=file.name;miStart();};r.onerror=()=>{mi.error='Could not read that file.';miRedraw();};r.readAsArrayBuffer(file);}
async function miRun(){if(mi.busy)return;const plan=miPlanNow(),adds=plan.rows.filter(e=>e.action==='add'),ups=plan.rows.filter(e=>e.action==='update');if(!adds.length&&!ups.length){notify('Nothing to import.');return;}
 const file=mi.file,res={added:[],warned:[],updated:[],skipped:plan.rows.filter(e=>e.action==='skip').map(e=>({line:e.line,name:e.name,reason:e.reason})),errors:plan.rows.filter(e=>e.action==='error').map(e=>({line:e.line,name:e.name,reason:e.errors.join('; ')}))};
 const of=new Map(),products=adds.map(e=>{const p=miProduct(e,file);of.set(p,e);return p;}),base=('Materials import'+(file?' — '+file:'')+' '+new Date().toISOString().slice(0,10)).slice(0,180),batches=miBatches(products,{name:base+' — part 999 of 999'});
 mi.busy=true;mi.step='run';mi.progress={done:0,total:adds.length+ups.length,label:'Starting…'};miRedraw();
 try{for(let b=0;b<batches.length;b++){const batch=batches[b];mi.progress.label='Adding new components: batch '+(b+1)+' of '+batches.length;miRedraw();
   const add=(e,p,id)=>{res.added.push({line:e.line,name:p.name,id,g:p.unitWeight,pack:p.packQuantity});const w=e.warnings.filter(x=>!/^No reference: saved as/.test(x));if(w.length)res.warned.push({line:e.line,name:p.name,reason:w.join('; ')});};
   try{const r=await command('importCatalogue',{name:base+' — part '+(b+1)+' of '+batches.length,products:batch});batch.forEach((p,j)=>add(of.get(p),p,r.products?.[j]?.id));}
   catch{// A batch is all or nothing: find the rows at fault one by one.
    for(const p of batch){const e=of.get(p);try{const r=await command('importCatalogue',{name:base+' — row '+e.line,products:[p]});add(e,p,r.products?.[0]?.id);}catch(err){res.errors.push({line:e.line,name:p.name,reason:err.message});}}}
   mi.progress.done+=batch.length;miRedraw();}
  for(let i=0;i<ups.length;i++){const e=ups[i],p=state.products.find(x=>x.id===e.target);mi.progress.label='Updating existing components: '+(i+1)+' of '+ups.length;if(i%5===0)miRedraw();
   if(!p)res.errors.push({line:e.line,name:e.name,reason:'That component is no longer in the catalogue'});else try{await command('override',miUpdate(e,p,file));res.updated.push({line:e.line,name:p.name,reason:'Now '+[e.g!=null?kg(e.g):'',e.pack!=null?num(e.pack)+' per pack':''].filter(Boolean).join(', ')});}catch(err){res.errors.push({line:e.line,name:e.name,reason:err.message});}mi.progress.done++;}}
 finally{mi.busy=false;mi.progress=null;mi.result=res;mi.step='done';}
 res.errors.sort((a,b)=>a.line-b.line);notify('Imported: '+num(res.added.length)+' added, '+num(res.updated.length)+' updated, '+num(res.skipped.length)+' skipped, '+num(res.errors.length)+(res.errors.length===1?' error.':' errors.'));
 try{await refresh(true);}catch(err){notify(err.message);miRedraw();}miTop('mi-import');}
async function miFixSave(ids){if(miFix.busy)return;const todo=[];for(const id of ids){const p=state.products.find(x=>x.id===id);if(!p)continue;const v=miFixValues(p,miFix.draft.get(id),miFix.note);if(v.error){miFix.msg.set(id,{bad:true,text:v.error});continue;}miFix.msg.delete(id);todo.push([p,v]);}
 const warn=todo.filter(([,v])=>v.warning);if(warn.length&&typeof confirm==='function'&&!confirm(warn.map(([p,v])=>p.name+': '+v.warning).slice(0,5).join('\n')+'\n\nSave anyway?')){miFixRedraw();return;}
 if(!todo.length){miFixRedraw();return;}miFix.busy=true;miFixRedraw();let saved=0;
 try{for(const [p,v] of todo){try{await command('override',v.input);saved++;miFix.done.set(p.id,{note:v.input.sourceNote});miFix.draft.delete(p.id);}catch(err){miFix.msg.set(p.id,{bad:true,text:err.message});}}}finally{miFix.busy=false;}
 if(saved)notify('Saved the figures for '+num(saved)+(saved===1?' component.':' components.'));try{await refresh(true);}catch(err){notify(err.message);miFixRedraw();}}
function miBindOnce(){if(miBound||typeof document==='undefined')return;miBound=true;const inPage=t=>!!t?.closest?.('.page-materials');
 document.addEventListener('input',e=>{const t=e.target;if(!inPage(t))return;
  if(t.id==='mi-text')mi.text=t.value;else if(t.id==='mi-maker')mi.maker=t.value;else if(t.id==='mi-region')mi.region=t.value;else if(t.id==='mi-fix-note'){miFix.note=t.value;for(const i of document.querySelectorAll('#mi-fix input[data-mi-fix="s"]'))i.placeholder=t.value.trim()?'Uses: '+t.value.trim():'';}
  else if(t.id==='mi-fix-search'){miFix.search=t.value;miFix.shown=60;const b=document.getElementById('mi-fix-body');if(b)b.outerHTML=miFixListHTML();}
  else if(t.dataset.miFix){const id=t.dataset.miId,d=miFix.draft.get(id)??{};d[t.dataset.miFix]=t.value;miFix.draft.set(id,d);t.closest('.mi-fix-row')?.classList.toggle('has-input',miHasDraft(d));const b=document.querySelector('#mi-fix-all b');if(b)b.textContent=num(miFilled());}});
 document.addEventListener('change',e=>{const t=e.target;if(!inPage(t))return;
  if(t.id==='mi-file'){miFile(t.files?.[0]);return;}
  if(t.id==='mi-delim'){mi.delim=t.value;miRead();}else if(t.id==='mi-header'){mi.header=Number(t.value);miGuess();}
  else if(t.dataset.miMap){mi.map[t.dataset.miMap]=Number(t.value);if(t.dataset.miMap==='weight'&&mi.header>=0)miSetUnit(miHeadUnit(mi.rows[mi.header]?.[Number(t.value)]));}
  else if(t.id==='mi-unit')mi.unit=t.value;else if(t.id==='mi-ver')mi.ver=t.value;else if(t.id==='mi-maker'||t.id==='mi-region'){if(mi.step!=='check')return;}
  else if(t.hasAttribute('data-mi-sys'))mi.sysMap[t.dataset.miSys]=t.value;
  else if(t.dataset.miEdit){const l=t.dataset.miLine;mi.edits[l]={...mi.edits[l],[t.dataset.miEdit]:t.value};}else return;
  miRedraw();});
 document.addEventListener('click',e=>{const t=e.target?.closest?.('.page-materials [data-mi-act]');if(!t||t.disabled)return;const a=t.dataset.miAct;
  if(a==='read'){const ta=document.getElementById('mi-text');if(ta)mi.text=ta.value;mi.file='';miStart();}
  else if(a==='back'){mi.step='input';mi.error='';miRedraw();}
  else if(a==='map'){mi.step='map';miRedraw();}
  else if(a==='check'){if(!(mi.map?.name>=0))return;mi.step='check';mi.shown=50;miRedraw();miTop('mi-import');}
  else if(a==='map-more'){mi.mapOpen=!mi.mapOpen;miRedraw();}
  else if(a==='delim'){mi.delim=t.dataset.miV;miRead();miRedraw();}
  else if(a==='filter'){mi.filter=t.dataset.miV;mi.shown=50;miRedraw();}
  else if(a==='dups'){const cat=new Set(miPlanNow().rows.filter(x=>x.dup?.kind==='catalogue').map(x=>String(x.line)));mi.dupDefault=t.dataset.miV;for(const k of Object.keys(mi.decisions))if(cat.has(k))delete mi.decisions[k];miRedraw();}
  else if(a==='dup'){mi.decisions[t.dataset.miLine]=t.dataset.miV;miRedraw();}
  else if(a==='blank'){const l=t.dataset.miLine;mi.edits[l]={...mi.edits[l],[t.dataset.miF]:''};miRedraw();}
  else if(a==='more'){mi.shown+=50;miRedraw();}
  else if(a==='import')miRun().catch(err=>{notify(err.message);miRedraw();});
  else if(a==='again'){if(mi.busy)return;const keep={maker:mi.maker,region:mi.region,ver:mi.ver};mi=miFresh();Object.assign(mi,keep);miRedraw();miTop('mi-import');}
  else if(a==='goto-import'){e.preventDefault();miGoImport();}
  else if(a==='fix-open'||a==='gaps-fix')miOpenFix();
  else if(a==='fix-close'){miFix=miFixFresh();render();document.getElementById('ml-catalogue')?.scrollIntoView({block:'start'});}
  else if(a==='fix-more'){miFix.shown+=60;miFixRedraw();}
  else if(a==='fix-save')miFixSave([t.dataset.miId]);
  else if(a==='fix-all')miFixSave([...miFix.draft].filter(([id,d])=>(String(d.w??'').trim()||String(d.k??'').trim())&&!miFix.done.has(id)).map(([id])=>id));});}
function planTools(){return '<div class="plan-tools"><button type="button" class="secondary" data-plan="zoom:1.25" title="Zoom in">+</button><span id="zoom-level">'+Math.round(planView.zoom*100)+'%</span><button type="button" class="secondary" data-plan="zoom:0.8" title="Zoom out">&minus;</button><button type="button" class="secondary" data-plan="rotate:-45" title="Turn the view left (the stillages stay where they are)">&#8634; Turn view</button><button type="button" class="secondary" data-plan="rotate:45" title="Turn the view right (the stillages stay where they are)">Turn view &#8635;</button><button type="button" class="secondary '+(planView.tilt?'current':'')+'" data-plan="tilt">'+(planView.tilt?'3D view':'Plan view')+'</button><button type="button" class="secondary" data-plan="reset">Reset view</button><span class="muted">Scroll to zoom &middot; drag empty ground to pan &middot; hover a stillage for its contents</span></div>';}
// The live panels shared by HOME and YARD (see part()): each reads the current state when a poll re-checks it.
const planPart=()=>part('plan','.scene .plan-wrap',()=>{const yard=state.yards[0];return planWrap(yard,yardSVG(yard,plannedContainers(),state.tasks,selected,state.trucks,state.resources,selectedWorker,planOpts({view:planView,planned:layoutDraft?new Set(Object.keys(layoutDraft.moves)):null})));},true);
const selectionPart=()=>part('selection','.scene .plan-selection',()=>selectionBar(state.yards[0]));
const crewPart=()=>part('crew','.worker-command-panel',()=>layoutDraft?plannerPanel(state.yards[0]):workerPanel(state.yards[0]));
// Under the plan the selection bar already carries where it is, Turn and Load onto, so the detail panel there leaves them out.
const detailPart=()=>part('detailIn','.selected-detail',()=>selected&&state.containers.some(c=>c.id===selected&&c.location===state.yards[0].id)?detail(true):'');
const homeCaption=()=>{const yard=state.yards[0],workers=state.resources.filter(r=>r.type==='WORKER'&&r.location===yard.id).length;return '<div class="scene-caption"><div class="map-legend"><span><i class="legend-dot stillage"></i>Stillages</span><span><i class="legend-dot cage"></i>Small-parts cages</span><span><i class="legend-dot loading"></i>Loading zone</span></div><span>'+(workerMoveMode==='JOB_TARGET'?'Click the plan to set the job location &middot; Esc cancels':layoutDraft?'Drag a stillage to a new spot &middot; drop it onto another stillage to stack it &middot; press R while dragging to turn it':workers+' workers on the yard &middot; left-click a worker to select &middot; right-click ground to move')+'</span></div>';};
