// ----- Set-up guide (Home, operations roles only): a checklist card under the Home hero that walks a new or emptied company to a yard that can work. -----
// sgSteps is pure (snapshot + account in, steps out) for the tests; the card is a Home part, so a poll re-checks it and patches it live; clicks go through one delegated listener.
// The steps still to do are full cards (the next one first); the finished ones fold into a row of small tick chips, so the guide gets shorter as the owner goes. On a phone only the next step shows until "Show all".
import {sgMount} from './art.js';
export const SG_STILLAGES=5;
const sgPlural=(n,one,many=one+'s')=>n+' '+(n===1?one:many);
export function sgSteps(s,acct){
 const yard=s?.yards?.[0]??null,here=x=>!!yard&&x.location===yard.id,res=s?.resources??[],workers=res.filter(r=>r.type==='WORKER'&&here(r)).length,forklifts=res.filter(r=>r.type==='FORKLIFT'&&here(r)).length;
 const trucks=(s?.trucks??[]).filter(t=>!!yard&&t.yard===yard.id&&!t.retired),heavy=trucks.filter(t=>t.payload>=10000000).length,light=trucks.length-heavy;
 const full=new Set();for(const l of s?.balances??[])if(l.quantity>0)full.add(l.container);const stills=(s?.containers??[]).filter(c=>here(c)&&c.type==='STILLAGE'&&!c.retired),empty=stills.filter(c=>!full.has(c.id)).length;
 const enabled=new Set((acct?.systems??[]).filter(x=>x.enabled).map(x=>x.id)),live=(s?.products??[]).filter(p=>!p.retired&&(!enabled.size||enabled.has(p.system))),demo=live.filter(p=>/DEMO/.test(p.verification??'')).length;
 // The catalogue counts once it holds real components: a DEMO-only list is made-up data. Missing weights / pack sizes are said on the step either way (they block moves and loading).
 const real=live.length-demo,demoOnly=live.length>0&&!real,gaps=live.filter(p=>p.unitWeight==null||p.packQuantity==null).length;
 let pieces=0;for(const r of s?.register??[])pieces+=Number(r.quantity)||0;if(!pieces)pieces=Number(s?.stockTotal)||0;
 const active=(s?.sites??[]).filter(x=>x.status==='ACTIVE').length,lists=(s?.loadLists??[]).filter(l=>!l.cancelled),dated=lists.filter(l=>l.neededOn).length;
 const pts=yard?.points??[],span=k=>pts.length?Math.round((Math.max(...pts.map(p=>p[k]))-Math.min(...pts.map(p=>p[k])))/100)/10:0;
 // A yard whose outline was never saved through the shape editor (shapeRev 0: an older yard) needs the owner to confirm it once; the outline itself may be right.
 const drawn=!!yard&&pts.length>=3,unconfirmed=drawn&&!((yard.shapeRev??0)>=1);
 // Stillages: N empty ones ready before the opening count; once stock is on the books N in all is enough (filling them must not undo the step). A yard past one page of containers is set up.
 const stillDone=empty>=SG_STILLAGES||(stills.length>=SG_STILLAGES&&pieces>0)||(s?.containerCount??0)>100;
 const step=(id,title,done,detail,why,needs=[],more={})=>({id,title,done:!!done,detail,why,needs,...more});
 const steps=[
  step('yard','Yard shape & size',drawn&&!unconfirmed,drawn?span('x')+' × '+span('y')+' m'+(unconfirmed?' · not checked yet':''):'No yard drawn yet',unconfirmed?'This outline has never been checked. Stillage rows, the loading bay and the gate are all placed inside it: confirm it matches your real yard, or change it.':'Stillage rows, the loading bay and the gate are all placed inside this outline. Make it match your real yard.',[],{unconfirmed}),
  step('crew','Crew',workers>=1,workers?sgPlural(workers,'worker')+' on the yard':'Nobody on the yard','Workers drive the forklifts and sling the loads. With no crew, nothing moves.'),
  step('forklift','Forklift',forklifts>=1,forklifts?sgPlural(forklifts,'forklift'):'No forklift yet','Every stillage move in the yard is a forklift move: stacking, turning and loading trucks.'),
  step('trucks','Trucks',trucks.length>=1,trucks.length?[heavy&&heavy+' × 12.5 t',light&&light+' × 2 t'].filter(Boolean).join(' · '):'No trucks yet','Yard lists go out on a truck: a 12.5 t for full loads, a 2 t for quick runs and returns.'),
  step('stillages','Stillages',stillDone,stills.length?sgPlural(stills.length,'stillage')+' · '+empty+' empty':'No stillages yet','Stock is kept in stillages. Have at least '+SG_STILLAGES+' empty ones ready before you record your opening stock.'),
  step('materials','Materials catalogue',real>=1,live.length?sgPlural(live.length,'component')+(demoOnly?' · DEMO list only':demo?' · '+demo+' demo':''):'No components yet',demoOnly?'The demo list is made-up data for trying the yard out. Import your supplier’s real catalogue before you go live.':'Stock, yard lists and truck weights all read from your catalogue. Import your supplier list, or load the demo list to try things out.',[],{demoOnly,gaps}),
  step('stock','Opening stock',pieces>0,pieces?sgPlural(pieces,'piece')+' on the books':'Nothing recorded yet','Count what is already in the yard and record it as original stock, so the books start true.',live.length?[]:['materials']),
  step('site','First client site',active>=1,active?sgPlural(active,'active site'):'No sites yet','Deliveries go to a client site. Add its name, address and contact; draw its shape later.'),
  step('list','First dated yard list',dated>=1,dated?sgPlural(dated,'dated yard list'):lists.length?sgPlural(lists.length,'yard list')+', none dated':'No yard lists yet','A yard list is what the yardsman loads and the truck delivers. Give it a date so it lands on the Schedule.',[!active&&'site',!live.length&&'materials'].filter(Boolean))];
 const done=steps.filter(x=>x.done).length;return {steps,done,total:steps.length,complete:done===steps.length,next:steps.find(x=>!x.done)?.id??null,moving:workers>0&&forklifts>0};
}
// Hidden per company and user in this browser (Hide this guide); a slim strip on Home and on the Overview offers it back while steps are left.
const sgKey=()=>'sg-hidden:'+(account?.company?.id??'')+':'+(account?.user?.id??'');
const sgHidden=()=>{try{return localStorage.getItem(sgKey())==='1';}catch{return false;}};
const sgSetHidden=on=>{try{if(on)localStorage.setItem(sgKey(),'1');else localStorage.removeItem(sgKey());}catch{}};
let sgAll=false;
const SG_ART={yard:'sg-yard',crew:'spr-worker',forklift:'spr-forklift',trucks:'spr-truck12',stillages:'spr-stillage',materials:'ml-rack',stock:'spr-bundle',site:'si-site',list:'sg-list'};
const SG_TICK='<svg viewBox="0 0 12 12" aria-hidden="true"><path d="M2.6 6.3 5 8.6l4.4-5" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const sgBtn=(act,label,cls='',extra='')=>'<button type="button" class="'+(cls||'sg-go')+'" data-sg="'+act+'"'+extra+'>'+label+'</button>';
const SG_NAMES={materials:'Materials catalogue',site:'Client site'};
const sgGapsLine=x=>'<p class="sg-gaps"><span><b>'+num(x.gaps)+'</b> '+(x.gaps===1?'component is':'components are')+' missing a weight or pack size.</span>'+sgBtn('gaps','Enter the missing figures &rarr;','text-button sg-gaps-btn')+'</p>';
function sgActions(x){const b=[];
 if(x.needs.length)return '<p class="sg-needs">'+(x.needs.length===1?'Do this first: ':'Do these first: ')+x.needs.map(n=>esc(SG_NAMES[n]??n)).join(', ')+'.</p>';
 if(x.id==='yard'){if(x.unconfirmed)b.push(sgBtn('confirm-shape','This outline is right'),sgBtn('shape','Check shape &amp; size','secondary sg-go'));else b.push(sgBtn('shape','Draw your yard'));}
 if(x.id==='crew')b.push(sgBtn('add:WORKER','+1 worker'));
 if(x.id==='forklift')b.push(sgBtn('add:FORKLIFT','+1 forklift'));
 if(x.id==='trucks')b.push(sgBtn('add:TRUCK12','Add a 12.5 t truck'),sgBtn('add:TRUCK2','Add a 2 t truck','secondary sg-go'));
 if(x.id==='stillages')b.push(sgBtn('add5:STILLAGE','+5 stillages'),sgBtn('add:STILLAGE','+1 stillage','secondary sg-go'));
 if(x.id==='materials'){b.push(sgBtn('import','Import materials'),sgBtn('go:MATERIALS','Open Materials list','secondary sg-go'));if(!state.products.length)b.push(sgBtn('seed','<span class="sg-demo">DEMO</span> Load demo materials','secondary sg-go sg-seed',' title="Adds a synthetic catalogue marked DEMO ONLY: not real manufacturer data"'));}
 // The intake list (searchable, grouped by system) is the quicker way to record a real opening count; the single-line opening-balance form stays as the second way.
 if(x.id==='stock'){if(!account.permissions.includes('stock.adjust'))return '<p class="sg-needs">An owner or general manager records opening stock.</p>';b.push(sgBtn('intake','Use Materials intake'),sgBtn('opening','Record original stock','secondary sg-go'));}
 if(x.id==='site')b.push(sgBtn('site','Create a site'));
 if(x.id==='list')b.push(sgBtn('list','Create a yard list'));
 return (x.id==='materials'&&x.gaps?sgGapsLine(x):'')+'<div class="sg-acts">'+b.join('')+'</div>';}
const sgArt=id=>id==='ml-rack'?mlImg('ml-rack','sg-pic'):sprite(id,'sg-pic');
