 const lead=g.moving?'Work down the list: each button does the step for you, and you can change everything later.':'Nothing in the yard can move yet: it needs at least one worker and one forklift. Work down the list: each button does the step for you.';
 return '<section class="panel sg-guide'+(sgAll?' sg-all':'')+'" aria-labelledby="sg-title"><div class="sg-head"><div class="sg-ring" role="img" aria-label="'+g.done+' of '+g.total+' set-up steps done"><svg viewBox="0 0 44 44" aria-hidden="true"><circle class="sg-ring-track" cx="22" cy="22" r="19"/><circle class="sg-ring-fill" cx="22" cy="22" r="19" stroke-dasharray="'+arc+' '+C+'" transform="rotate(-90 22 22)"/></svg><b>'+g.done+'<small>/'+g.total+'</small></b></div>'
  +'<div class="sg-title"><span class="section-kicker">SET-UP GUIDE &middot; '+sgPlural(left,'step')+' to go</span><h2 id="sg-title">Set up your real yard</h2><p>'+lead+'</p></div><button type="button" class="text-button sg-hide" data-sg="hide">Hide this guide</button></div>'
