// ----- Schedule: every yard list and single request on the day it is needed, by the truck that runs it. Dates are 'YYYY-MM-DD' strings; the server's calendar (state.calendar) says what today is, and all date arithmetic is string arithmetic in UTC (never the browser clock). -----
let schedWeek=null,schedX=null,schFlash={id:null,until:0},schCache=null;const schedOpen=new Set(),schedDraft=new Map();
const SCH_DAYS=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],SCH_MONTHS=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'],SCH_SLOTS=[['ANY','Any time'],['AM','Morning (AM)'],['PM','Afternoon (PM)']],SLOT_ORDER={AM:0,ANY:1,PM:2};
const cal=()=>state?.calendar??null;
const dYMD=d=>String(d).split('-').map(Number);
const dUTC=d=>{const [y,m,x]=dYMD(d);return Date.UTC(y,m-1,x);};
const dAdd=(d,n)=>{const [y,m,x]=dYMD(d);return new Date(Date.UTC(y,m-1,x+n)).toISOString().slice(0,10);};
const dWeekday=d=>(new Date(dUTC(d)).getUTCDay()+6)%7;
