// One pass over containers and balances per render: containers by location, pieces and non-empty lines per container, product names by id.
function siIndex(){const byLoc=new Map(),pcs=new Map(),lines=new Map();for(const c of state.containers){let a=byLoc.get(c.location);if(!a)byLoc.set(c.location,a=[]);a.push(c);}for(const l of state.balances){if(!(l.quantity>0))continue;pcs.set(l.container,(pcs.get(l.container)??0)+l.quantity);let a=lines.get(l.container);if(!a)lines.set(l.container,a=[]);a.push(l);}return {byLoc,pcs,lines,pname:new Map(state.products.map(p=>[p.id,p.name]))};}
const siAgo=iso=>{const t=Date.parse(iso);if(!(t>0))return '';const m=Math.round((Date.now()-t)/60000);return m<1?'just now':m<60?m+' min ago':m<1440?Math.round(m/60)+' h ago':new Date(t).toLocaleDateString();};
const siStat=(art,label,value,sub,fill=null)=>'<div class="hud-stat" role="listitem"><span class="hud-icon">'+art+'</span><span class="hud-text"><span class="hud-label">'+label+'</span><b class="hud-num">'+value+'</b>'+(fill==null?'':'<i class="hud-bar" aria-hidden="true"><b data-style="width:'+fill+'%"></b></i>')+'<span class="hud-sub">'+sub+'</span></span></div>';
function siHero(ix){const ops=isOps(),sites=state.sites,active=sites.filter(s=>s.status==='ACTIVE'),ids=new Set(sites.map(s=>s.id));let pieces=0,still=0,cages=0;for(const s of sites)for(const c of ix.byLoc.get(s.id)??[]){pieces+=ix.pcs.get(c.id)??0;if(c.type==='CAGE')cages++;else still++;}
 const here=state.trucks.filter(t=>t.status==='AT_SITE'&&ids.has(t.at)).length,road=state.trucks.filter(t=>t.status==='IN_TRANSIT'&&ids.has(t.destination)).length,lists=(state.loadLists??[]).filter(l=>!l.cancelled&&l.status!=='DELIVERED'),waiting=lists.filter(l=>l.status==='OPEN'&&!l.truck).length,single=state.requests.filter(r=>!r.loadList&&['REQUESTED','ALLOCATED','PARTIALLY ALLOCATED'].includes(r.status)).length,last=sites.map(s=>s.lastDeliveryAt).filter(Boolean).sort().pop();
 const sub=[active.length===1?'1 active site':active.length+' active sites',sites.length>active.length?(sites.length-active.length)+' archived':'',last?'last delivery '+siAgo(last):''].filter(Boolean).join(' &middot; ');
 const jump=sites.length>1?'<nav class="si-jump" aria-label="Jump to a site"><span class="si-jump-label">Jump to</span>'+sites.map(s=>'<a href="#si-site-'+s.id+'" class="si-jump-chip'+(s.status==='ACTIVE'?'':' off')+'">'+esc(s.name)+'</a>').join('')+'</nav>':'';
 return '<div class="si-hero page-hero"><div class="si-hero-art">'+siSceneArt()+'</div><div class="si-hero-top">'+heroEyebrow()+'<h1 class="si-hero-title">'+(ops?'Site directory':'Your sites')+'</h1><p class="si-hero-sub hero-sub">'+(sites.length?sub:ops?'No sites yet. Create one below.':'No sites are assigned to you yet.')+'</p>'+heroActions(jump)+'</div>'
 +'<div class="hud-stats si-hud" role="list" aria-label="Sites at a glance">'+siStat(siImg('si-site'),'Active sites',num(active.length)+(sites.length>active.length?'<small>/ '+num(sites.length)+'</small>':''),active.length?'Taking deliveries':'Nothing running',null)+siStat(siImg('spr-bundle'),'Stock on sites',num(pieces),still+cages?still+(still===1?' stillage':' stillages')+(cages?' &middot; '+cages+(cages===1?' cage':' cages'):''):'Nothing on site yet',null)+siStat(siImg('spr-truck12'),'Trucks at sites',num(here),road?road+(road===1?' truck':' trucks')+' on the way':'None on the road',null)+siStat(siImg('si-docket'),'Open yard lists',num(lists.length),waiting?waiting+'<span class="ph-long"> waiting for a truck</span><span class="ph-short"> waiting</span>':single?single+(single===1?' single request':' single requests'):lists.length?'All have a truck':'<span class="ph-long">Nothing requested</span><span class="ph-short">None open</span>',null)+'</div>'+heroBanner()+'</div>';}
// A chip with a line glyph; links for email and phone.
const siChip=(g,html,cls='')=>'<span class="si-chip'+(cls?' '+cls:'')+'">'+siGlyph(g)+'<span>'+html+'</span></span>';
function siKeys(s,boxes,pieces,trucks,crew){const cranes=crew.filter(r=>r.type==='CRANE').length,workers=crew.filter(r=>r.type==='WORKER').length,cages=boxes.filter(c=>c.type==='CAGE').length;const k=(art,v,l)=>'<div class="si-key"><span class="si-key-art">'+art+'</span><span><b>'+v+'</b><small>'+l+'</small></span></div>';
 return '<div class="si-keys" role="list" aria-label="'+esc(s.name)+' at a glance">'+k(siImg('spr-bundle'),num(pieces),'pieces on site')+k(siImg(cages&&cages===boxes.length?'spr-cage':'spr-stillage'),num(boxes.length),boxes.length===1?(cages?'cage':'stillage'):cages?'stillages &amp; cages':'stillages')+k(siImg('spr-truck12'),num(trucks.length),trucks.length===1?'truck here':'trucks here')+k(cranes?siImg('si-crane'):siImg('spr-worker'),workers+(cranes?'<small class="si-plus">+'+cranes+'</small>':''),cranes?(workers===1?'worker':'workers')+' &middot; '+(cranes===1?'crane':cranes+' cranes'):'site crew')+'</div>';}
// Stillages and cages on the site as compact sprite tiles (same select / drag behaviour as the container cards).
function siTiles(id,boxes,ix){const drag=isOps()?'true':'false';if(!boxes.length)return '<p class="si-none">'+siImg('spr-stillage')+'<span>No stillages or cages here yet.</span></p>';return '<div class="si-tiles" data-keep-scroll="si-tiles-'+id+'">'+boxes.map(c=>{const pcs=ix.pcs.get(c.id)??0,lines=ix.lines.get(c.id)??[],good=c.condition==='SERVICEABLE',what=lines.map(l=>l.quantity+' × '+(ix.pname.get(l.product_id)??name(l.product_id)));return '<button type="button" class="si-tile'+(c.id===selected?' is-selected':'')+(good?'':' attention')+'" data-select="'+c.id+'" draggable="'+drag+'" title="'+esc(c.name+' · '+c.type+(what.length?' · '+what.join(', '):' · empty')+(good?'':' · '+c.condition))+'"><span class="si-tile-art">'+siImg(c.type==='CAGE'?'spr-cage':'spr-stillage')+(pcs?'<b class="si-tile-pcs">'+num(pcs)+'</b>':'')+'</span><span class="si-tag">'+esc(c.name)+'</span><small class="si-tile-what">'+(lines.length?esc(ix.pname.get(lines[0].product_id)??name(lines[0].product_id)).replace(/(\d) (?=(?:mm|m|kg|t)\b)/g,'$1&nbsp;')+(lines.length>1?' <em>+'+(lines.length-1)+' more</em>':''):'Empty')+'</small>'+(good?'':'<small class="si-flag-bad">'+esc(c.condition)+'</small>')+(c.support?'<small class="si-stacked">stacked</small>':'')+'</button>';}).join('')+'</div>';}
