function prListBar(l,controls){if(!l||(!controls&&l.delivery&&!prToSend(l)))return '';const pick=!l.cancelled&&((!l.delivery&&l.status!=='DELIVERED')||prToSend(l));return '<div class="pr-bar"><span class="pr-bar-label">'+prGlyph('print')+'Paperwork</span>'+(pick?prButton('pick',l.id,'Print pick list'):'')+(l.cancelled&&!l.delivery?'':prButton('docket',l.id,'Print docket'))+'</div>';}
