function gsPill(e){if(e.kind==='MATERIAL')return '<span class="gs-pill '+(e.count?'yard':'off')+'">'+(e.count?'<b>'+num(e.count)+'</b> in yard':'None in yard')+'</span>';return e.pill?'<span class="gs-pill '+esc(e.tone??'')+'">'+esc(e.pill)+'</span>':'';}
