// ----- Alerts and minimum stock levels (al*): the bell in the top bar, the Alerts drawer, the 'Needs attention' strip on Home and Overview, the minimum-level editor
// (Materials tiles and the missing-figures rows) and the below-minimum marks on the stockpile tiles and the hover card. The server derives the alerts (state.alerts);
// nothing here decides what is an alert. The bell, the drawer body and the Home strip are parts, so a Home poll patches only them; clicks go through one delegated listener.
import {alImg} from './art.js';
LIVE_KEYS.add('alerts');
const AL_KIND={LOW_STOCK:['Below minimum','al-low'],OVERDUE:['Overdue','al-late'],DUE_TODAY:['Due today','al-list'],CLASH:['Truck clash','al-clash'],BLOCKED:['Blocked move','al-blocked'],DAMAGED:['Out of service','al-damaged']};
const AL_SEV=[['high','Urgent','Do these first'],['medium','Soon','Today or coming up'],['low','Worth a look','When you have a moment']];
