// ---- The minimum-level editor: one modal dialog (its open state pauses the poll, so a refresh never rebuilds it mid-typing). ----
const alBelowOf=id=>alData(state).below?.[id]??null;
// A tile's below-minimum mark and the stockpile memo key that follows it.
const alTileMark=id=>alBelowOf(id)?' al-low':'';
const alBelowKey=()=>{const b=alData(state).below;return b?Object.keys(b).sort().map(k=>k+'='+b[k].free).join(','):'';};
// The Materials tile / fixer row chip: the minimum (red when below it), or a quiet 'Set minimum' for the roles that may set one.
