 const range=d&&d.days===hcDays?'<span class="hc-range">'+hcYear(d.from)+' &ndash; today, '+hcLong(d.today)+(hcAt?' <span class="hc-updated">&middot; updated '+new Date(hcAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})+'</span>':'')+'</span>':'<span class="hc-range">'+(hcErr?'':'Loading the last '+hcDays+' days&hellip;')+'</span>';
