 const start=s.startPieces??0,end=s.endPieces??0;
 const facts='<dl class="hr-facts"><div><dt>Hire to</dt><dd><b>'+esc(s.site.client||s.site.name)+'</b><span>'+esc([s.site.client?'Site: '+s.site.name:'',s.site.address].filter(Boolean).join(' · '))+'</span></dd></div><div><dt>Period</dt><dd><b>'+hrDay(s.from)+' &ndash; '+hrDay(s.to)+'</b><span>'+hrN(s.days,'day')+(s.clamped?' &middot; up to today':'')+'</span></dd></div><div><dt>Pieces on hire</dt><dd><b>'+num(start)+' &rarr; '+num(end)+'</b><span>at the start &rarr; at the end</span></dd></div><div><dt>Rates</dt><dd><b>'+hrRatesWord(s)+'</b><span>AUD, ex GST &middot; GST '+d.gstPercent+'%'+(s.rateChanges?' &middot; a price changed in these dates':'')+'</span></dd></div></dl>';
 const actions='<div class="hr-actions"><button type="button" class="hr-print" data-hr-print>'+prGlyph('print')+'<span>Print statement</span></button><a class="button-link hr-csv" href="/api/hire.csv?'+esc(hrQuery()||'site='+encodeURIComponent(s.site.id))+'" download>'+STK_DL+'<span>Download CSV</span></a>'+(s.demo?'<span class="hr-chip demo" title="Demonstration products are on this statement: it prints with a DEMO watermark.">DEMO data &middot; prints with a watermark</span>':'')+'</div>';
 if(!s.lines.length)return facts+'<div class="hr-empty">'+sprite('spr-truck2')+'<div><b>Nothing was on hire at '+esc(s.site.name)+' in these dates.</b><p>Pick other dates, or &ldquo;Since first delivery&rdquo;.</p></div></div>';
 const rate=l=>l.rate.priced?'<span class="hr-rate-val">'+hrRate(l.rate)+'</span>'+(l.rate.source==='site'?'<span class="hr-chip site">Site rate</span>':'')+(l.split?'<small class="hr-rate-when">'+hrWhen(l)+'</small>':'')+'<small class="hr-rate-note">'+hrRateNote(l.rate)+'</small>':'<span class="hr-chip warn">No rate</span><button type="button" class="text-button hr-set" data-hr-rate="'+esc(l.product.id)+'">Set rate</button>';
