 const truck=ops?'<label class="rt-truck-field">Truck<select name="truck"><option value="">Book a truck later</option>'+schTrucks().map(t=>'<option value="'+esc(t.id)+'"'+(t.id===d.truck?' selected':'')+'>'+esc(t.name)+(t.status==='AT_SITE'&&t.at===s.id?' (here now)':'')+'</option>').join('')+'</select></label>':'<p class="rt-hint">The yard office books the truck.</p>';
